effect.shader:
void main(){
vec2 uv=acScreenNorm,dir=vec2(cos(direction),sin(direction));
vec4 src=texture2DCv(inputImg.texture,uv); float lum=dot(src.rgb,vec3(0.299,0.587,0.114));
vec3 acc=vec3(0.0); float weight=0.0;
for(int i=0;i<8;i++){
float fi=float(i),enabled=step(fi+0.5,layers);
float z=fi/max(layers-1.0,1.0), w=pow(fade,fi)*enabled;
vec2 off=dir*spread*z*(0.35+lum*lumaDepth);
vec4 cr=texture2DCv(inputImg.texture,clamp(uv-off*1.12,0.0,1.0));
vec4 cg=texture2DCv(inputImg.texture,clamp(uv-off,0.0,1.0));
vec4 cb=texture2DCv(inputImg.texture,clamp(uv-off*0.88,0.0,1.0));
acc+=vec3(cr.r,cg.g,cb.b)*w; weight+=w;
}
vec3 stacked=acc/max(weight,0.001);
float rim=clamp(length(stacked-src.rgb)*2.2,0.0,1.0);
stacked+=vec3(0.12,0.05,0.18)*rim;
gl_FragColor=vec4(mix(src.rgb,stacked,mixAmount),src.a);
}
